<script setup lang="ts">
import AppIcon from '@/Components/AppIcon.vue';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { ref } from 'vue';
interface Book { id: number; title: string; publication_year: number | null; publisher: string | null; isbn: string | null; copies_count: number; category: { name: string } | null; authors: { id: number; display_name: string }[]; copies: { id: number; inventory_number: string; status: string }[] }
interface PageLink { url: string | null; label: string; active: boolean }
const props = defineProps<{ books: { data: Book[]; links: PageLink[]; from: number | null; to: number | null; total: number }; filters: { search: string } }>();
const search = ref(props.filters.search); const page = usePage(); const canCreate = page.props.auth.permissions.includes('books.create');
const submitSearch = () => router.get(route('books.index'), { search: search.value }, { preserveState: true, replace: true });
</script>
<template><Head title="Catalogue"/><AuthenticatedLayout><template #header><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="mb-1 text-xs font-bold uppercase tracking-[0.16em] text-primary-600">Catalogue</p><h1 class="font-heading text-2xl font-bold text-slate-800">Ouvrages</h1><p class="mt-2 text-sm text-slate-500">Titres bibliographiques et disponibilité des exemplaires.</p></div><div class="flex flex-wrap gap-2"><a v-if="$page.props.auth.permissions.includes('imports.view')" :href="route('book-exports.xlsx')" class="inline-flex h-10 items-center rounded-md border border-slate-200 px-4 text-sm font-bold text-slate-600">Exporter Excel</a><Link v-if="$page.props.auth.permissions.includes('imports.view')" :href="route('book-imports.index')" class="inline-flex h-10 items-center rounded-md border border-primary-200 px-4 text-sm font-bold text-primary-600">Importer</Link><Link v-if="canCreate" :href="route('books.create')" class="inline-flex h-10 items-center justify-center rounded-md bg-primary-600 px-4 text-sm font-bold text-white hover:bg-primary-700">Ajouter un ouvrage</Link></div></div></template>
<div v-if="$page.props.flash?.success" class="mb-5 rounded-md border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700">{{ $page.props.flash.success }}</div><section class="dw-card overflow-hidden"><div class="border-b border-slate-100 p-4 sm:p-5"><form class="flex max-w-xl gap-2" @submit.prevent="submitSearch"><div class="relative flex-1"><AppIcon name="search" class="absolute start-3.5 top-1/2 h-5 w-5 -translate-y-1/2 text-slate-400"/><input v-model="search" class="dw-field ps-11" placeholder="Titre, auteur, ISBN ou n° d’enregistrement…"/></div><button class="rounded-md bg-slate-800 px-4 text-sm font-bold text-white">Rechercher</button></form></div><div class="overflow-x-auto"><table class="w-full min-w-[1100px] text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-400"><tr><th class="px-5 py-3 text-start">Titre et auteur</th><th class="px-5 py-3 text-start">Catégorie</th><th class="px-5 py-3 text-start">Édition</th><th class="px-5 py-3 text-start">N° d’enregistrement</th><th class="px-5 py-3 text-start">ISBN</th><th class="px-5 py-3 text-center">Exemplaires</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="book in books.data" :key="book.id" class="hover:bg-slate-50/70"><td class="px-5 py-4"><p class="font-semibold text-slate-700">{{ book.title }}</p><p class="mt-1 text-xs text-slate-400">{{ book.authors.map(a => a.display_name).join(', ') }}</p></td><td class="px-5 py-4 text-slate-500">{{ book.category?.name || 'Non classé' }}</td><td class="px-5 py-4 text-slate-500">{{ [book.publisher, book.publication_year].filter(Boolean).join(' · ') || '—' }}</td><td class="px-5 py-4"><div v-if="book.copies.length" class="flex max-w-xs flex-wrap gap-1"><span v-for="copy in book.copies" :key="copy.id" class="rounded bg-primary-50 px-2 py-1 font-mono text-[11px] font-bold text-primary-700 dark:bg-primary-900/30 dark:text-primary-300">{{ copy.inventory_number }}</span></div><span v-else class="text-slate-400">Aucun</span></td><td class="px-5 py-4 font-mono text-xs text-slate-500">{{ book.isbn || '—' }}</td><td class="px-5 py-4 text-center"><span class="rounded-full bg-primary-50 px-2.5 py-1 text-xs font-bold text-primary-700">{{ book.copies_count }}</span></td></tr><tr v-if="!books.data.length"><td colspan="6" class="px-5 py-16 text-center text-slate-400">Aucun ouvrage trouvé.</td></tr></tbody></table></div><div v-if="books.total" class="flex flex-col gap-3 border-t border-slate-100 px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><p class="text-xs text-slate-400">Résultats {{ books.from }}–{{ books.to }} sur {{ books.total }}</p><div class="flex flex-wrap gap-1"><template v-for="link in books.links" :key="link.label"><Link v-if="link.url" :href="link.url" preserve-state :class="link.active ? 'bg-primary-600 text-white' : 'border border-slate-200 text-slate-500'" class="min-w-9 rounded px-3 py-2 text-center text-xs" v-html="link.label"/><span v-else class="min-w-9 rounded border border-slate-100 px-3 py-2 text-center text-xs text-slate-300" v-html="link.label"/></template></div></div></section></AuthenticatedLayout></template>
